<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';
$cats=$conn->query("SELECT id,category_name FROM expense_categories WHERE status='Active' ORDER BY category_name")->fetchAll();$expenses=$conn->query("SELECT e.*,ec.category_name,u.full_name FROM expenses e LEFT JOIN expense_categories ec ON ec.id=e.category_id LEFT JOIN users u ON u.id=e.user_id ORDER BY e.id DESC LIMIT 50")->fetchAll();$month=(float)$conn->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE YEAR(expense_date)=YEAR(CURDATE()) AND MONTH(expense_date)=MONTH(CURDATE())")->fetchColumn();$today=(float)$conn->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE expense_date=CURDATE()")->fetchColumn();$flash=$_SESSION['expense_flash']??null;unset($_SESSION['expense_flash']);
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?><main class="content"><style>.grid{display:grid;grid-template-columns:360px 1fr;gap:18px}.panel{background:#fff;padding:20px;border-radius:12px;box-shadow:0 1px 4px #0001}.stats{display:flex;gap:15px;margin:15px 0}.stat{background:#fff;padding:15px;border-radius:10px;flex:1}.stat strong{display:block;font-size:22px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:5px}.field input,.field select{width:100%;padding:10px;box-sizing:border-box;border:1px solid #dbe3ec;border-radius:7px}.btn{border:0;border-radius:7px;padding:11px 15px;background:#004a99;color:#fff;font-weight:700;cursor:pointer;width:100%}.flash{padding:12px;background:#ecfdf5;color:#166534;border-radius:8px;margin-bottom:12px}.table{width:100%;border-collapse:collapse}.table th{background:#004a99;color:#fff;padding:10px;text-align:left}.table td{padding:10px;border-bottom:1px solid #e5e7eb;font-size:13px}@media(max-width:900px){.grid{grid-template-columns:1fr}.stats{flex-direction:column}}</style><h1>Expenses</h1><p>Record and monitor business operating expenses.</p><?php if($flash):?><div class="flash"><?=e($flash)?></div><?php endif;?><div class="stats"><div class="stat"><strong>KES <?=number_format($today,2)?></strong><small>Today</small></div><div class="stat"><strong>KES <?=number_format($month,2)?></strong><small>This Month</small></div></div><div class="grid"><div class="panel"><h3>Record Expense</h3><form method="post" action="store.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Expense Title</label><input name="expense_title" required maxlength="150"></div><div class="field"><label>Category</label><select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['category_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Amount</label><input type="number" name="amount" min=".01" step=".01" required></div><div class="field"><label>Payment Method</label><select name="payment_method"><option>Cash</option><option>M-Pesa</option><option>Bank</option><option>Cheque</option><option>Other</option></select></div><div class="field"><label>Date</label><input type="date" name="expense_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Description</label><input name="description" maxlength="500"></div><button class="btn">Save Expense</button></form></div><div class="panel"><h3>Expense Register</h3><div style="overflow:auto"><table class="table"><thead><tr><th>Number</th><th>Date</th><th>Title</th><th>Category</th><th>Amount</th><th>Method</th><th>Recorded By</th></tr></thead><tbody><?php foreach($expenses as $e):?><tr><td><?=e($e['expense_number'])?></td><td><?=e($e['expense_date'])?></td><td><?=e($e['expense_title'])?></td><td><?=e($e['category_name']??'')?></td><td>KES <?=number_format((float)$e['amount'],2)?></td><td><?=e($e['payment_method'])?></td><td><?=e($e['full_name']??'')?></td></tr><?php endforeach;?></tbody></table></div></div></div></main><?php require_once __DIR__.'/../../includes/footer.php';?>